-- Stack Built Project Health Dashboard — one-time database setup.
-- Creates all 7 tables the app needs, locks them down so only signed-in
-- @stack.llc people can touch them, then loads your 6 real active Ressio
-- projects (Homes at the Knoll Lot 27/28, Lot 1 Hyrum, Lot 17 Knoll
-- Subdivision, Knoll Sub Phase 2, Elevate at 12th Phase 1) with their
-- milestones and tasks. Safe to run once. Employees are NOT included here
-- — the app creates each person's account automatically the first time
-- they sign in with their @stack.llc Google account.

CREATE TABLE IF NOT EXISTS "employees" (
	"id" text PRIMARY KEY NOT NULL,
	"email" text NOT NULL,
	"name" text NOT NULL,
	"role" text NOT NULL,
	"created_at" timestamp NOT NULL,
	CONSTRAINT "employees_email_unique" UNIQUE("email")
);
