	"status" text DEFAULT 'UPCOMING' NOT NULL,
	"planned_finish" timestamp NOT NULL,
	"actual_finish" timestamp,
	"ressio_line_item_id" text,
	"baseline_captured" boolean DEFAULT false NOT NULL
);
