-- ===== Row Level Security =====
-- The new website talks to this database directly from the browser (using
-- a public "anon" key), instead of going through a server you control. So
-- the database itself has to enforce "only signed-in @stack.llc people can
-- read or write anything" — that's what this section does. Without it,
-- anyone with the anon key (which is not a secret — it's meant to be
-- public) could read or edit everything.

CREATE OR REPLACE FUNCTION is_stack_employee() RETURNS boolean AS $$
  SELECT coalesce(auth.jwt() ->> 'email', '') LIKE '%@stack.llc'
$$ LANGUAGE sql STABLE;

ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE project_milestones ENABLE ROW LEVEL SECURITY;
ALTER TABLE task_instances ENABLE ROW LEVEL SECURITY;
ALTER TABLE template_milestones ENABLE ROW LEVEL SECURITY;
ALTER TABLE template_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE ressio_sync_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE employees ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "stack employees full access" ON projects;
CREATE POLICY "stack employees full access" ON projects FOR ALL USING (is_stack_employee()) WITH CHECK (is_stack_employee());

DROP POLICY IF EXISTS "stack employees full access" ON project_milestones;
CREATE POLICY "stack employees full access" ON project_milestones FOR ALL USING (is_stack_employee()) WITH CHECK (is_stack_employee());

DROP POLICY IF EXISTS "stack employees full access" ON task_instances;
CREATE POLICY "stack employees full access" ON task_instances FOR ALL USING (is_stack_employee()) WITH CHECK (is_stack_employee());

DROP POLICY IF EXISTS "stack employees can read" ON template_milestones;
CREATE POLICY "stack employees can read" ON template_milestones FOR SELECT USING (is_stack_employee());

DROP POLICY IF EXISTS "stack employees can read" ON template_tasks;
CREATE POLICY "stack employees can read" ON template_tasks FOR SELECT USING (is_stack_employee());

DROP POLICY IF EXISTS "stack employees can read" ON ressio_sync_events;
CREATE POLICY "stack employees can read" ON ressio_sync_events FOR SELECT USING (is_stack_employee());
-- No insert/update policy on ressio_sync_events for regular employees —
-- only the daily Ressio-sync job writes here, using a separate key
-- (the "service role" key) that bypasses these rules entirely.

DROP POLICY IF EXISTS "stack employees can view employees" ON employees;
CREATE POLICY "stack employees can view employees" ON employees FOR SELECT USING (is_stack_employee());

DROP POLICY IF EXISTS "employees can create own record" ON employees;
CREATE POLICY "employees can create own record" ON employees FOR INSERT
  WITH CHECK (is_stack_employee() AND email = (auth.jwt() ->> 'email'));

DROP POLICY IF EXISTS "employees can update own record" ON employees;
CREATE POLICY "employees can update own record" ON employees FOR UPDATE
  USING (email = (auth.jwt() ->> 'email'))
  WITH CHECK (email = (auth.jwt() ->> 'email'));

-- Stops someone from editing their own "role" to ADMIN through the app —
-- role changes for other people only happen through Supabase's own Table
-- Editor (Danny's dashboard login bypasses these rules entirely, same as
-- the SQL Editor you're running this file in right now).
CREATE OR REPLACE FUNCTION prevent_self_role_change() RETURNS trigger AS $$
BEGIN
  IF auth.role() <> 'service_role' AND NEW.role IS DISTINCT FROM OLD.role THEN
    NEW.role := OLD.role;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS employees_prevent_self_role_change ON employees;
CREATE TRIGGER employees_prevent_self_role_change
  BEFORE UPDATE ON employees
  FOR EACH ROW EXECUTE FUNCTION prevent_self_role_change();

